import XCTest
@testable import PacerCore

final class SharedGzipTests: XCTestCase {
    func testCompleteMemberAndStrictInputAndExpansionBounds() throws {
        let valid = Data(base64Encoded: "H4sIAAAAAAAC/6uuBQBDv6ajAgAAAA==")!
        XCTAssertEqual(try ClaudeActivityTelemetry.decodedBody(valid, encoding: "gzip"), Data("{}".utf8))
        XCTAssertThrowsError(try ClaudeActivityTelemetry.decodedBody(Data(valid.dropLast()), encoding: "gzip"))
        XCTAssertThrowsError(try ClaudeActivityTelemetry.decodedBody(valid + Data([0]), encoding: "gzip"))
        XCTAssertThrowsError(try ClaudeActivityTelemetry.decodedBody(valid + valid, encoding: "gzip"))
        var corrupt = valid; corrupt[corrupt.count - 8] ^= 1
        XCTAssertThrowsError(try ClaudeActivityTelemetry.decodedBody(corrupt, encoding: "gzip"))
        XCTAssertThrowsError(try ClaudeActivityTelemetry.decodedBody(Data(base64Encoded: "")!, encoding: "gzip"))
        XCTAssertThrowsError(try ClaudeActivityTelemetry.decodedBody(Data(), encoding: "gzip"))
        XCTAssertThrowsError(try ClaudeActivityTelemetry.decodedBody(valid, encoding: "br"))
        XCTAssertThrowsError(try ClaudeActivityTelemetry.decodedBody(Data(repeating: 0, count: ClaudeActivityTelemetry.maximumBodyBytes + 1), encoding: "identity"))
    }
}
